/**
 * Visual formats. Every asset in a package gets its own format, chosen by the
 * Art Director to fit the idea and the channel, so a campaign looks native to
 * each place it's posted rather than one key visual stamped everywhere.
 *
 * "code" formats are rendered as exact, editable layouts (text must be right).
 * "image" formats are generated by the image model; until one is connected
 * they show the art direction instead of a fake picture.
 */
export type FormatKind = "code" | "image";

export interface FormatDef {
  id: string;
  name: string;
  kind: FormatKind;
  use: string;
}

export const FORMATS: FormatDef[] = [
  { id: "meme", name: "Meme", kind: "code", use: "Top/bottom caption over an image. For jokes people repost." },
  { id: "headline", name: "News headline", kind: "code", use: "A news-style story card. For stunts that should look like they're already in the press." },
  { id: "notification", name: "Push notifications", kind: "code", use: "A phone lock screen with stacked notifications. For mystery, urgency and running jokes." },
  { id: "receipt", name: "Receipt", kind: "code", use: "A printed till receipt. For absurd purchases, deals and itemised jokes." },
  { id: "document", name: "Official document", kind: "code", use: "A letter, certificate or contract with a seal and signature. For deals, clauses and mock-formal announcements." },
  { id: "chat", name: "Group chat", kind: "code", use: "A chat thread. For reactions, 'did you see this' moments and leaked conversations." },
  { id: "ticket", name: "Ticket or pass", kind: "code", use: "An event ticket or boarding pass. For events, drops and invitations." },
  { id: "poster", name: "Typographic poster", kind: "code", use: "Big type, one line. For bold statements and teasers." },
  { id: "screen", name: "App or web screen", kind: "code", use: "A product, tool or website screen. For internet-native objects: bots, generators, extensions, games." },
  { id: "quote", name: "Quote card", kind: "code", use: "One line in big quotes with a handle. For a line the internet will repeat." },
  { id: "photo", name: "Photograph", kind: "image", use: "Documentary or editorial photo of a real-world stunt, object or place." },
  { id: "illustration", name: "Illustration", kind: "image", use: "Drawn or painted artwork: maps, comics, editorial illustration." },
  { id: "render3d", name: "3D render", kind: "image", use: "A hyper-real or stylised 3D object or scene." },
  { id: "product", name: "Product shot", kind: "image", use: "A studio shot of a (parody) product, merch item or object." },
  { id: "collage", name: "Collage", kind: "image", use: "Cut-and-paste, zine or scrapbook style." },
];

export const FORMAT_IDS = FORMATS.map((f) => f.id) as [string, ...string[]];

export const ASSET_KEYS = ["x", "ig", "carousel", "story", "tiktok", "landing", "telegram", "discord"] as const;
export type AssetKey = (typeof ASSET_KEYS)[number];

export const PALETTES = ["night", "paper", "acid", "candy", "mono"] as const;
export type Palette = (typeof PALETTES)[number];

export interface VisualSpec {
  asset: AssetKey;
  format: string;
  headline: string;
  lines: string[];
  caption: string | null;
  artDirection: string;
  imagePrompt: string | null;
  palette: Palette;
  imageUrl?: string | null;
  imageModel?: string | null;
}

export function formatById(id: string): FormatDef | undefined {
  return FORMATS.find((f) => f.id === id);
}

/** Aspect each asset is shown at, used when generating images. */
export const ASSET_ASPECT: Record<AssetKey, "16:9" | "1:1" | "9:16" | "4:5"> = {
  x: "16:9",
  ig: "1:1",
  carousel: "1:1",
  story: "9:16",
  tiktok: "9:16",
  landing: "4:5",
  telegram: "16:9",
  discord: "16:9",
};
